{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "We included the following study designs: (Cluster) randomised controlled trials ((C)RCTs) Non-­ randomised controlled trials (nRCTs) Controlled before-­ after (CBA) studies. Interrupted time series (ITS) with a clearly defined time point of intervention introduction and at least three data points both before and after the intervention. ... The study design was determined using the Cochrane EPOC group algorithm. 25 No restrictions were placed on language, publication date or publication status of the studies. In case an article published in a language other than English or German was deemed eligible for inclusion based on the abstract screening, we had it translated into German.",
      "reason": "The manuscript explicitly lists eligible study designs (including ITS requirements), describes use of the EPOC algorithm to determine design, and specifies language/publication date/status handling; population eligibility is provided in text_2."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "No restrictions were placed on language, publication date or publication status of the studies. In case an article published in a language other than English or German was deemed eligible for inclusion based on the abstract screening, we had it translated into German.",
      "reason": "Report characteristics (language, publication date, publication status) are explicitly addressed and no restrictions applied; translation procedure is described."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement was found distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_26",
      "quote": "Due to the scarcity of the articles and the heterogeneity of the data, we conducted structured syntheses without meta-­ analyses.",
      "reason": "The manuscript states that structured (non‑meta‑analytic) syntheses were performed, but it does not clearly specify the groups used in each synthesis or link those groups to the comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_27",
      "quote": "This is mostly due to our restriction to only include studies with a robust study design (eg, CBA or ITS studies). Only three of nine (33%) included studies had a thorough study design that could be clearly identified as either a CBA 37 or an ITS. 35 41",
      "reason": "The manuscript provides a rationale for restricting eligibility to robust study designs (CBA/ITS) and discusses the impact of that restriction in the limitations."
    }
  ],
  "confidence": 85
}

